function addCondition(type){try{api.addCondition({type,value:type==='force'?Number($('force').value):0,direction:['dx','dy','dz'].map(id=>Number($(id).value))});status('条件を登録しました。まだ解析計算は行っていません。');}catch(error){status(error.message);}}
