function probeAt(event){try{if(!lastAnalysis?.result)throw Error('解析結果を表示してから測定してください。');const rect=$('canvas').getBoundingClientRect();mouse.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(analysisLayer.visible?analysisLayer.children.filter(o=>o.isMesh):meshes,false)[0];if(!hit)return;let point=hit.point.toArray();if(analysisLayer.visible){const ids=lastAnalysis.mesh.surface[hit.faceIndex].nodes,p=hit.object.geometry.attributes.position,t=new THREE.Triangle(...[0,1,2].map(i=>new THREE.Vector3().fromBufferAttribute(p,hit.faceIndex*3+i))),w=t.getBarycoord(hit.point,new THREE.Vector3()).toArray();point=[0,1,2].map(k=>ids.reduce((sum,id,i)=>sum+w[i]*lastAnalysis.mesh.nodes[id*3+k],0));}const values=window.analysisApi.probe(point);$('probe-result').textContent=(language==='en'?'Position':'位置')+' ['+point.map(v=>v.toFixed(3)).join(', ')+'] mm\n'+(values.peakPressurePa!==undefined?'Pressure '+values.peakPressurePa.toPrecision(5)+' Pa peak / SPL '+values.splDb.toFixed(2)+' dB RMS / Phase '+values.phase.toFixed(4)+' rad':values.temperature!==undefined?'Temperature '+values.temperature.toFixed(3)+' °C / Heat flux '+Math.hypot(...values.flux).toPrecision(5)+' W/m²':'Displacement '+values.magnitudeMm.toPrecision(5)+' mm / von Mises '+(values.vonMisesPa/1e6).toPrecision(5)+' MPa');}catch(e){status(e.message);}}

