for(const id of ['thermal-stress','solid-temperature','reference-temperature','gravity-enabled','gravity-x','gravity-y','gravity-z','physics','transient-heat','time-step','time-steps','initial-temperature','volumetric-source','acoustic-frequency','sound-speed','air-density','acoustic-loss','reference-pressure','acoustic-sweep','sweep-start','sweep-end','sweep-count','receiver-x','receiver-y','receiver-z'])$(id).onchange=()=>{projectRevision++;clearAnalysis();};

async function runAnalysis(solve){if(solve&&materialDirty&&$('physics').value!=='acoustic'){status('物性の変更を登録してから解析してください。');return;}const revision=projectRevision;clearAnalysis();$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;try{const options={size:Number($('mesh-size').value),method:$('solver').value,adaptive:$('adaptive-run').checked,maxRounds:Number($('adaptive-rounds').value)};const output=await(solve?analysis.analyze(options):analysis.generateMesh(options));if(revision!==projectRevision)throw Error('Inputs changed during calculation; run again');lastAnalysis=output;showAnalysis();$('mesh-summary').textContent=output.mesh.summary.nodeCount+' 節点 / '+output.mesh.summary.elementCount+' 四面体 · '+output.mesh.summary.volumeMm3.toFixed(2)+' mm³ / 品質 '+output.mesh.summary.minQuality.toPrecision(3)+' / 品質0.2未満 '+output.mesh.summary.qualityHistogram[0]+' 要素';if(output.boundary)$('region-report').textContent=output.boundary.reports.map(r=>r.type+': 面積誤差 '+(r.relativeAreaError*100).toFixed(1)+'%').join(' / ');if(output.result){const r=output.result;$('result-field').value=r.kind==='acoustic'?'pressure':r.kind==='thermal'?'temperature':'displacement';showAnalysis();$('result-summary').textContent=r.kind==='acoustic'?'周波数 '+r.frequency.toFixed(1)+' Hz / 最大音圧 '+r.maxPressurePa.toPrecision(5)+' Pa（peak） / 最大SPL '+r.maxSplDb.toFixed(2)+' dB（RMS） / 残差 '+r.residual.toExponential(2):r.kind==='thermal'?'温度 '+r.minTemperature.toFixed(3)+' → '+r.maxTemperature.toFixed(3)+' °C / 対流による流入 '+r.convectionHeatW.toPrecision(5)+' W / 温度境界の供給 '+r.reactionHeatW.toPrecision(5)+' W / エネルギー収支誤差 '+r.energyBalanceErrorW.toExponential(2)+' W / 残差 '+r.residual.toExponential(2):'最大変位 '+r.maxDisplacementMm.toPrecision(5)+' mm / 最大von Mises '+(r.maxVonMisesPa/1e6).toPrecision(5)+' MPa / 残差 '+r.residual.toExponential(2)+' / 反力 ['+r.reaction.map(v=>v.toFixed(3)).join(', ')+'] N / 合力 ['+r.applied.map(v=>v.toFixed(3)).join(', ')+'] N / 体積荷重 ['+r.bodyLoadN.map(v=>v.toFixed(4)).join(', ')+'] N';$('result-export').disabled=false;if(r.constraintRegionReactions?.length){const caption=document.createElement('p');caption.textContent='領域の節点反力（共有節点を含む、全体座標）';$('constraint-reactions').append(caption);for(const group of r.constraintRegionReactions){const p=document.createElement('p');p.textContent='#'+(group.conditionIndex+1)+' ['+group.force.map(v=>v.toFixed(4)).join(', ')+'] N'+(group.directionalReactionN!==null?' / 指定方向 '+group.directionalReactionN.toFixed(4)+' N':'');$('constraint-reactions').append(p);}}if(r.sweep){const table=document.createElement('table');const head=document.createElement('tr');for(const label of ['Hz','Pa peak','dB RMS']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const v of r.sweep.samples){const row=document.createElement('tr');for(const text of [v.frequency.toFixed(1),v.peakPressurePa.toPrecision(4),v.splDb.toFixed(2)]){const td=document.createElement('td');td.textContent=text;row.append(td);}table.append(row);}$('sweep-results').append(table);}} if(output.adaptive){const text=document.createElement('p');text.textContent=(output.adaptive.converged?'収束条件を満たしました。':'反復上限で停止。収束未確認。')+' '+output.adaptive.history.map(h=>'#'+h.round+': '+h.elements+' elements / '+h.maxDisplacementMm.toPrecision(4)+' mm').join(' → ');$('result-summary').append(text);}status(solve?'解析が完了しました。':'体積メッシュを生成しました。');}catch(e){status(e.message);}finally{$('mesh-run').disabled=$('solve-run').disabled=false;$('cancel-run').disabled=true;}}
$('mesh-run').onclick=()=>runAnalysis(false);$('solve-run').onclick=()=>runAnalysis(true);$('cancel-run').onclick=()=>analysis.cancel();
for(const id of ['result-field','deform-scale','volume-wire'])$(id).onchange=showAnalysis;
$('setup-view').onclick=()=>{analysisLayer.visible=false;group.visible=true;markers.visible=true;};
$('result-export').onclick=()=>{if(!lastAnalysis)return;const url=URL.createObjectURL(new Blob([JSON.stringify(lastAnalysis)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='analysis-result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
new ResizeObserver(()=>{const rect=$('canvas').parentElement.getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();}).observe($('canvas').parentElement);
for(const input of document.querySelectorAll('#material-fields input,#material-grade,#material-source,#material-notes'))input.oninput=()=>{materialDirty=true;$('material-status').textContent='未登録の物性変更があります。';};
demo();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});

installLanguage();
document.addEventListener('studio-language',()=>{if(['Curved sample · Ø24 × 60 mm','曲面サンプル · Ø24 × 60 mm'].includes(modelName)){$('name').textContent=language==='en'?'Curved sample · Ø24 × 60 mm':'曲面サンプル · Ø24 × 60 mm';}});

$('convection-add').onclick=()=>{try{api.addCondition({type:'convection',value:Number($('convection-h').value),ambientTemperature:Number($('ambient-temperature').value)});status('条件を登録しました。');}catch(e){status(e.message);}};
function convectionExample(){thermalExample();api.removeCondition(0);api.selectCondition(0);api.removeCondition(0);api.addCondition({type:'convection',value:100,ambientTemperature:20});const p=meshes[0].geometry.attributes.position.array,bottom=[];for(let t=0;t<p.length/9;t++)if([2,5,8].every(k=>p[t*9+k]===0))bottom.push(t);api.selectTriangles(0,bottom);api.addCondition({type:'temperature',value:100});modelName=language==='en'?'Convection reference sample':'対流放熱の参照サンプル';$('name').textContent=modelName;status('放熱サンプルを設定しました。先端温度の参照値は46.667 °Cです。');}
$('convection-demo').onclick=convectionExample;window.analysisApi.loadConvectionExample=convectionExample;

$('local-mesh-add').onclick=()=>{try{const size=Number($('local-mesh-size').value),radius=Number($('local-mesh-radius').value),base=Number($('mesh-size').value);if(size<base*.15||size>base)throw Error('局所サイズは全体の15〜100%にしてください。');api.setMeshSettings({refinements:[...meshSettings.refinements,...selectedRefinements(getProject(),{size,radius})]});status('局所メッシュ設定を登録しました。');}catch(e){status(e.message);}};
$('local-mesh-clear').onclick=()=>api.setMeshSettings({refinements:[]});

function cavityExample(){acousticExample();const g=new THREE.BoxGeometry(20,20,40).toNonIndexed();g.translate(10,10,20);const d=geometryData(g);d.faceIds=d.faceIds.map((_,i)=>Math.floor(i/2));setModel([d],language==='en'?'Pressure-driven rigid-wall cavity':'剛壁空洞（音圧駆動）');sourceModel={kind:'box',bounds:[0,0,0,20,20,40]};api.setStudy({...getProject().study,kind:'acoustic',frequency:2143.75,lossFactor:.02,sweep:false,sweepStart:1500,sweepEnd:2800,sweepCount:9,receiverPoint:[10,10,39]});const bottom=[];for(let t=0;t<d.positions.length/9;t++)if([2,5,8].every(k=>d.positions[t*9+k]===0))bottom.push(t);api.selectTriangles(0,bottom);api.addCondition({type:'acousticPressure',value:1});$('mesh-size').value=5;status('一面を1 Paで駆動、他の5面は剛壁。一次共鳴の参照周波数は2143.75 Hzです。');g.dispose();}
$('cavity-demo').onclick=cavityExample;window.analysisApi.loadCavityExample=cavityExample;

for(const [id,type,input]of [['pressure-add','pressure','pressure-input'],['normal-traction-add','normalTraction','normal-traction']])$(id).onclick=()=>{try{api.addCondition({type,value:Number($(input).value)*1000});status('条件を登録しました。');}catch(e){status(e.message);}};
function pressureExample(){analysisExample();api.selectCondition(1);api.removeCondition(1);api.addCondition({type:'pressure',value:1e6});api.setMaterialProperties({...materialProperties,density:1000});api.setStudy({...getProject().study,kind:'structural',gravityEnabled:true,gravity:[0,0,-10]});modelName=language==='en'?'Pressure and gravity reference':'圧力と重力の参照サンプル';$('name').textContent=modelName;$('adaptive-run').checked=false;status('圧力1 MPaと加速度−10 m/s²。参照変位0.040008 mm、反力100.04 Nです。');}
$('pressure-demo').onclick=pressureExample;window.analysisApi.loadPressureExample=pressureExample;

function addDisplacement(value){const axis=Number($('constraint-axis').value),frame=$('constraint-local').checked?frameFromEuler(['frame-x','frame-y','frame-z'].map(id=>Number($(id).value)),axis):undefined;api.addCondition({type:'displacement',value,direction:[[1,0,0],[0,1,0],[0,0,1]][axis],frame});}
for(const [id,zero]of [['direction-fixed',true],['displacement-add',false]])$(id).onclick=()=>{try{addDisplacement(zero?0:Number($('prescribed-mm').value));status('条件を登録しました。');}catch(e){status(e.message);}};
function displacementExample(){analysisExample();api.selectCondition(1);api.removeCondition(1);api.addCondition({type:'displacement',value:.04,frame:frameFromEuler([0,-90,0],0)});$('constraint-local').checked=true;$('constraint-axis').value='0';$('frame-x').value=0;$('frame-y').value=-90;$('frame-z').value=0;$('prescribed-mm').value=.04;$('adaptive-run').checked=false;modelName=language==='en'?'Local-axis displacement reference':'局所座標の指定変位サンプル';$('name').textContent=modelName;status('局所X（全体Z）に0.04 mm。可動面の参照反力100 N、固定面は−100 Nです。');}
$('displacement-demo').onclick=displacementExample;window.analysisApi.loadDisplacementExample=displacementExample;

const caseStore=createCaseStore();
function viewCase(index){if($('cancel-run').disabled===false)throw Error('先に実行中の計算を中止してください。');const saved=caseStore.list()[index];if(!saved)throw Error('Unknown case');const output=prepareCaseView(saved);api.loadProject(output.input);const o=output.calculation.options;$('mesh-size').value=o.size;$('solver').value=o.method;$('adaptive-run').checked=o.adaptive;$('adaptive-rounds').value=o.maxRounds;lastAnalysis=output;showAnalysis();$('result-export').disabled=false;$('mesh-summary').textContent=output.mesh.summary.nodeCount+' 節点 / '+output.mesh.summary.elementCount+' 四面体';$('result-summary').textContent=saved.name+' · '+caseStore.compare()[index].metrics.map(m=>m.value.toPrecision(5)+' '+m.unit).join(' / ');status('保存時の入力と結果を表示しています。');return {name:saved.name,kind:output.result.kind};}

function renderCases(){const select=$('thermal-case');select.replaceChildren();for(const [i,c]of caseStore.compare().entries())if(c.kind==='thermal'){const option=document.createElement('option');option.value=i;option.textContent=c.name;select.append(option);}const root=$('case-list');root.replaceChildren();const rows=caseStore.compare();for(const [index,c] of caseStore.list().entries()){const item=document.createElement('article');const title=document.createElement('strong');title.textContent=c.name;item.append(title);const summary=document.createElement('p');summary.textContent=rows[index].kind+' · '+rows[index].metrics.map(m=>({maxDisplacementMm:'最大変位',maxVonMisesPa:'最大von Mises',minTemperature:'最低温度',maxTemperature:'最高温度',maxPressurePa:'最大音圧',maxSplDb:'最大SPL'}[m.key])+': '+m.value.toPrecision(5)+' '+m.unit).join(' / ');item.append(summary);for(const [label,action] of [['保存結果を3D表示',()=>viewCase(index)],['入力を複製して復元',()=>{api.loadProject(c.output.input);const o=c.output.calculation.options;$('mesh-size').value=o.size;$('solver').value=o.method;$('adaptive-run').checked=o.adaptive;$('adaptive-rounds').value=o.maxRounds;}],['削除',()=>{caseStore.remove(index);renderCases();}]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{try{action();}catch(e){status(e.message);}};item.append(b);}root.append(item);}}
window.caseApi=Object.freeze({...caseStore,view:viewCase,add(name,output){const result=caseStore.add(name,output);renderCases();return result;},import(value){caseStore.import(value);renderCases();},remove(index){caseStore.remove(index);renderCases();}});
$('case-add').onclick=()=>{try{if(!lastAnalysis?.result)throw Error('Run an analysis first');window.caseApi.add($('case-name').value,lastAnalysis);}catch(e){status(e.message);}};
$('case-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(caseStore.export())],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='simulation-cases.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('case-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000000)throw Error('Case archive exceeds 100 MB');window.caseApi.import(JSON.parse(await file.text()));}catch(error){status(error.message);}finally{e.target.value='';}};

function thermalStressExample(){displacementExample();api.selectCondition(1);api.removeCondition(1);api.addCondition({type:'displacement',value:0,direction:[0,0,1]});api.setMaterialProperties({...getProject().materialProperties,expansion:1e-5});api.setStudy({...getProject().study,thermalStress:true,temperature:80,referenceTemperature:20});modelName=language==='en'?'Restrained thermal expansion':'拘束した熱膨張サンプル';$('name').textContent=modelName;status('60 Kの温度上昇。軸方向の参照応力−0.6 MPa、両端反力は±60 Nです。');}
$('thermal-stress-demo').onclick=thermalStressExample;window.analysisApi.loadThermalStressExample=thermalStressExample;

function applyThermalCase(index){const c=caseStore.list()[index];if(!c||c.output.result.kind!=='thermal')throw Error('Choose a saved thermal case');const p=getProject();if(!p.sourceModel||JSON.stringify(p.sourceModel)!==JSON.stringify(c.output.input.sourceModel))throw Error('Use the same solid geometry for temperature transfer');api.setStudy({...p.study,kind:'structural',thermalStress:true,temperatureSource:{name:c.name,mesh:{nodes:c.output.mesh.nodes,tetrahedra:c.output.mesh.tetrahedra},temperature:c.output.result.temperature}});$('thermal-source-name').textContent=c.name;return api.getSummary();}
window.analysisApi.applyThermalCase=applyThermalCase;
$('thermal-case-apply').onclick=()=>{try{applyThermalCase(Number($('thermal-case').value));}catch(e){status(e.message);}};
$('thermal-case-clear').onclick=()=>{const p=getProject(),study={...p.study};delete study.temperatureSource;api.setStudy(study);$('thermal-source-name').textContent='';};
